def mrr(rankings, relevant):
    if not rankings:
        return 0.0
    total = 0.0
    for ranking, rel in zip(rankings, relevant):
        for i, d in enumerate(ranking, start=1):
            if d in rel:
                total += 1 / i
                break
    return round(total / len(rankings), 3)

